```c
void
put_on_cmdline(char_u *s, int len, int append)
{
    int		newlen;
    char_u	*newbuf;

    if (len < 0)
        len = (int)STRLEN(s);

    if (append)
    {
        newlen = ccline.cmdlen + len;
        if (newlen >= ccline.cmdbuffsize)
